store_rust_api:
// Normative Rust2021 signature surface only; bodies/constructors remain private.
// Existing EditorActorV0, SelectedArtifactV0, EditorSaveAllocationV0,
// EditorSaveBindingV0, ObjectDescriptor, Envelope and StoreStatus reused.
// Desktop-defined opaque types, names aligned with Desktop proposer:
// NativeSaveEnrollment, SaveIssuer, SaveSelectionPin, PendingSaveInstance,
// SaveActivationStamp, NativeSaveBindings, DesktopSaveLaunch, SaveOrigin,
// NativeSaveIntent, NativeDraftSnapshot, BoundNativeSource, NativeSaveCall,
// NativeSaveEntry, NativeSaveGuard, NativeSaveOriginalGuard, SaveGateGuard.
// These are concrete actual-owner proofs, never caller traits or callbacks.

pub struct NativeSaveFixtureProfile {
 pub origin_ms:u64, pub initial_objects:Vec<InitialObject>,
 pub fixture_signing_seed:[u8;32], pub fixture_key_id:String,
} // native Save only: 1..=3 objects, each ASCII<=4096, max2 actual Desktop sessions

pub struct PreparedNativeSaveStore { /* private actual host/controller/Core/issuer */ }
pub struct NativeSaveInitFailure { /* private real witness/issuer/Core/root owners */ }
pub struct NativeSaveExposeFailure { /* private complete pending/setup/tag/Core owners */ }
pub struct NativeSaveActivation { /* private actual Core/Grant/tag/owned stamp */ }
pub struct PairedNativeSaveLaunch { /* private Desktop carrier + actual Store endpoint */ }
pub struct NativeAllocatedOperation { /* private original ticket/record/delivered claim */ }
pub struct NativeDraftSource { /* private real Data/intent/snapshot/allocation/bound proof */ }
pub struct NativeDraftWriteLease { /* private actual source/Core/Grant/intent */ }
pub struct NativeSelectedRead { /* private immutable bytes + live selected-read query */ }
pub struct NativeReceiptRead { /* private original binding + actual lookup authority */ }
pub struct RegisteredNativeSave { /* private claimed-once original call/Core/Grant */ }
pub struct NativeSaveReply { /* private actual wire, leases, original/publisher owners */ }
pub struct OriginalNativeSave { /* private actual one execution ticket and Core lineage */ }
pub struct NativeSaveRecovery { /* private original-only lookup owner; no mutation */ }
pub struct QuiescedNativeSaveOwner { /* nonClone actual Core/issuer/inventory/minima */ }
pub struct NativeSaveReopenFailure { pub error: FixtureError, pub owner: QuiescedNativeSaveOwner }

impl StoreFixture {
 pub fn prepare_native_save(root:&Path, profile:NativeSaveFixtureProfile,
   witness:RegistryWitness, enrollment:NativeSaveEnrollment)
   -> Result<PreparedNativeSaveStore,NativeSaveInitFailure>;
 pub fn reopen_native_save(owner:QuiescedNativeSaveOwner)
   -> Result<PreparedNativeSaveStore,NativeSaveReopenFailure>;
}
impl PreparedNativeSaveStore {
 pub fn host(&self)->&StoreHost;
 pub fn controller(&self)->&FixtureController;
 pub fn pin_selection(&self, chrome:&PeerContext, object:u64, ttl_ms:u64)
   -> Result<SaveSelectionPin,StoreStatus>; // captures Instant before validation
 pub fn activate_save(&self,pending:&PendingSaveInstance)
   -> Result<NativeSaveActivation,NativeSaveExposeFailure>;
}
impl NativeSaveActivation {
 pub fn pair_launch(&self,launch:&mut Option<DesktopSaveLaunch>)
   -> Result<PairedNativeSaveLaunch,NativeSaveExposeFailure>;
}
impl PairedNativeSaveLaunch {
 pub fn desktop(&self)->&DesktopSaveLaunch;
 pub fn endpoint(&self)->&EditorEndpoint;
}
impl StoreHost {
 pub fn register_native_save(&self, endpoint:&EditorEndpoint, call:NativeSaveCall)
   -> Result<RegisteredNativeSave,NativeSaveRegistrationFailure>;
 pub fn execute_native_save(&self, original:&RegisteredNativeSave)
   -> Result<NativeSaveReply,StoreStatus>; // once, actual typed368 control
 pub fn source_for_intent(&self, endpoint:&EditorEndpoint,
   allocation:&NativeAllocatedOperation, intent:&NativeSaveIntent)
   -> Result<NativeDraftSource,StoreStatus>; // no caller body/hash/generation
 pub fn selected_lease(&self, query:&RegisteredNativeSave, descriptor:&ObjectDescriptor)
   -> Result<NativeSelectedRead,StoreStatus>;
 pub fn receipt_lease(&self, query:&RegisteredNativeSave, descriptor:&ObjectDescriptor)
   -> Result<NativeReceiptRead,StoreStatus>;
 pub fn observe_original(&self, lookup:NativeSaveCall, original:&OriginalNativeSave)
   -> Result<NativeOriginalReply,NativeSaveRegistrationFailure>;
 pub fn recover_original(&self, lookup:NativeSaveCall, owner:&NativeSaveRecovery)
   -> Result<NativeOriginalReply,NativeSaveRegistrationFailure>;
 pub fn native_save_producers(&self)->Result<Vec<ProducerId>,StoreStatus>;
 pub fn join_native_save_finished(&self,id:&ProducerId)
   -> Result<JoinedProducerProof,StoreStatus>;
}
impl RegisteredNativeSave {
 pub fn original(&self)->&OriginalNativeSave; // real owner exists before execution/Err
}
impl OriginalNativeSave {
 pub fn observation_origin(&self)->&OriginalRecoveryOrigin;
}
impl NativeSaveRecovery { pub fn origin(&self)->&OriginalRecoveryOrigin; }
impl NativeSaveReply {
 pub fn wire(&self)->&Envelope;
 pub fn producers(&self)->&[ProducerId];
 pub fn selected(&self)->Option<&NativeSelectedRead>;
 pub fn take_editor(&mut self)->Result<NativeEditor,StoreStatus>; // once-only actual Core initialization
 pub fn receipt(&self)->Option<&NativeReceiptRead>;
 pub fn allocation(&self)->Option<&NativeAllocatedOperation>;
 pub fn original(&self)->&OriginalNativeSave;
 pub fn into_parts(self)->NativeSaveReplyParts;
}
impl NativeAllocatedOperation {
 pub fn observation(&self)->EditorSaveAllocationV0; // historical data, not claim minting
}
impl NativeDraftSource {
 pub fn descriptor(&self)->ObjectDescriptor;
 pub fn bound(&self)->&BoundNativeSource;
 pub fn write_lease(&self)->Result<NativeDraftWriteLease,StoreStatus>;
}
impl NativeDraftWriteLease {
 pub fn copy_from(&self,offset:u32,input:&[u8])->Result<(),StoreStatus>;
}
impl NativeSelectedRead {
 pub fn descriptor(&self)->ObjectDescriptor;
 pub fn copy_into(&self,offset:u32,out:&mut[u8])->Result<(),StoreStatus>;
}
impl NativeReceiptRead {
 pub fn descriptor(&self)->ObjectDescriptor;
 pub fn copy_into(&self,offset:u32,out:&mut[u8])->Result<(),StoreStatus>;
}
// Closed observable outcomes. Values cannot construct the opaque owners above.
pub enum NativeOriginalObservation {
 AllocationPending, // no operation/source/receipt claim, content dispatch count0
 NoAllocation,     // actual owned completion+joins and validated no-allocation proof
 AllocationRetained { allocation:EditorSaveAllocationV0, commit_dispatched:bool },
 CommitPending { binding:EditorSaveBindingV0 },
 Receipt { binding:EditorSaveBindingV0, receipt:NativeReceiptRead },
}
pub struct NativeOriginalReply { /* original exact wire/observation + actual lookup IDs */ }
impl NativeOriginalReply {
 pub fn wire(&self)->&Envelope; // actual lookup9/10 or7/8 correlation
 pub fn original_wire(&self)->Option<&Envelope>;
 pub fn allocation(&self)->Option<&NativeAllocatedOperation>; // actual once-delivery claim
 pub fn take_allocation(&mut self)->Option<NativeAllocatedOperation>;
 pub fn observation(&self)->&NativeOriginalObservation;
 pub fn producers(&self)->&[ProducerId];
}
impl FixtureController {
 pub fn recovery_for_original(&self,chrome:&PeerContext,original:&OriginalNativeSave)
   -> Result<NativeSaveRecovery,StoreStatus>;
 pub fn pause_native_save(&self,endpoint:&EditorEndpoint,point:PausePoint)
   -> Result<PauseToken,FixtureError>;
 pub fn drop_next_native_reply(&self,endpoint:&EditorEndpoint)->Result<(),FixtureError>;
 pub fn quiesce_native_save(&self,timeout_ms:u64)
   -> Result<QuiescedNativeSaveOwner,FixtureError>;
 // Existing advance_time/seed_counter/fail_next_io/stop_at_phase/release/evidence reused,
 // with native-specific admission/ownership enforced rather than native_only bypass.
}
impl QuiescedNativeSaveOwner {
 pub fn fence_snapshot(&self)->NativeSaveFenceSnapshot; // diagnostic, not token minting
}
impl NativeSaveInitFailure { pub fn status(&self)->StoreStatus; pub fn observation(&self)->NativeSaveInitObservation; }
impl NativeSaveExposeFailure { pub fn status(&self)->StoreStatus; pub fn observation(&self)->NativeSaveExposeObservation; }
pub struct NativeSaveRegistrationFailure { /* actual consumed call/Core + held producers */ }
impl NativeSaveRegistrationFailure {
 pub fn status(&self)->StoreStatus;
 pub fn call(&self)->&NativeSaveCall;
 pub fn original(&self)->Option<&OriginalNativeSave>;
 pub fn producers(&self)->&[ProducerId];
}


// Closed move-out carrier lets the real editor retain original on all paths.
pub type NativeSaveInitObservation = InitObservation;
pub type NativeSaveExposeObservation = ExposeObservation;
pub struct NativeSaveReplyParts {
 pub wire:Envelope, pub original:OriginalNativeSave,
 pub allocation:Option<NativeAllocatedOperation>, pub selected:Option<NativeSelectedRead>,
 pub receipt:Option<NativeReceiptRead>, pub editor:Option<NativeEditor>,
 pub producers:Vec<ProducerId>,
}

// Exact closed diagnostic-only fields. Vec bounds checked before iteration.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OriginalTicketKind { Allocate, Commit }
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OriginalTicketCompletion { Pending, JoinedReturned, JoinedPanicked }
pub struct OriginalTicketObservation {
 pub original_request:[u8;88], pub origin_id:u64, pub intent_id:u64,
 pub kind:OriginalTicketKind, pub actor:EditorActorV0,
 pub object_id:u64, pub original_epoch:u64,
 pub allocation:Option<EditorSaveAllocationV0>, pub binding:Option<EditorSaveBindingV0>,
 pub closed:bool, pub commit_dispatched:bool, pub completion:OriginalTicketCompletion,
}
pub struct NativeSaveFenceSnapshot {
 pub schema_version:u32, // 1
 pub base:FenceSnapshot, // <=3 objects; held service+IO <=64 total; IO<=2
 pub original_tickets:Vec<OriginalTicketObservation>, // <=96, no body/stack trace
}
pub use desktop_service::editor_dev::NativeJoinObservation; // actual roster owner defines it

impl FixtureController { pub fn probe_inactive_native_save(&self,chrome:&PeerContext,pending:&PendingSaveInstance,pause:&NativeSavePause)->Result<InactiveSaveStoreObservation,StoreStatus>; }
pub struct InactiveSaveStoreObservation { pub grant_status:Result<(),StoreStatus> }
impl StoreHost { pub fn start_native_save(&self,original:&RegisteredNativeSave)->Result<NativeSaveExecution,StoreStatus>; }
pub struct NativeSaveExecution { /* private actual original, ready slot and charged producer owners */ }
impl NativeSaveExecution { pub fn poll_once(&self)->Result<Option<NativeSaveReply>,StoreStatus>; }
